use wgpu::*;
use std::sync::mpsc;
fn main() {
 let marker="// Native ordinary-world D3D GREATER predicate after reference-byte normalization.";
 let environment=include_str!("../../../assets/shaders/native_environment_fog.wgsl");let terrain=include_str!("../../../assets/shaders/terrain_height_blend.wgsl");let helper=environment.split(marker).nth(1).unwrap();assert_eq!(helper,terrain.split(marker).nth(1).unwrap());
 let code=format!("{}{}",helper,r#"
 @vertex fn vertex(@builtin(vertex_index) index:u32)->@builtin(position) vec4<f32> {
  let points=array<vec2<f32>,3>(vec2<f32>(-1.0,-1.0),vec2<f32>(3.0,-1.0),vec2<f32>(-1.0,3.0));
  return vec4<f32>(points[index],0.0,1.0);
 }
 @fragment fn fragment(@builtin(position) position:vec4<f32>)->@location(0) vec4<f32> {
  let alpha=f32(u32(position.x))/255.0;let reference=f32(u32(position.y))/255.0;
  if !native_alpha_accepts(alpha,reference) {discard;}
  return vec4<f32>(1.0,0.0,0.0,1.0);
 }
 "#);
 let mut descriptor=InstanceDescriptor::new_without_display_handle();descriptor.backends=Backends::VULKAN;let instance=Instance::new(descriptor);let adapter=bevy::tasks::block_on(instance.request_adapter(&RequestAdapterOptions {power_preference:PowerPreference::HighPerformance,force_fallback_adapter:false,compatible_surface:None})).unwrap();let info=adapter.get_info();let(device,queue)=bevy::tasks::block_on(adapter.request_device(&DeviceDescriptor {required_limits:Limits::downlevel_defaults(),..Default::default()})).unwrap();
 let shader=device.create_shader_module(ShaderModuleDescriptor {label:Some("production native alpha predicate"),source:ShaderSource::Wgsl(code.into())});let pipeline=device.create_render_pipeline(&RenderPipelineDescriptor {label:None,layout:None,vertex:VertexState {module:&shader,entry_point:Some("vertex"),buffers:&[],compilation_options:Default::default()},primitive:PrimitiveState::default(),depth_stencil:None,multisample:MultisampleState::default(),fragment:Some(FragmentState {module:&shader,entry_point:Some("fragment"),targets:&[Some(ColorTargetState {format:TextureFormat::Rgba8Unorm,blend:None,write_mask:ColorWrites::ALL})],compilation_options:Default::default()}),multiview_mask:None,cache:None});
 let size=Extent3d {width:256,height:256,depth_or_array_layers:1};let texture=device.create_texture(&TextureDescriptor {label:None,size,mip_level_count:1,sample_count:1,dimension:TextureDimension::D2,format:TextureFormat::Rgba8Unorm,usage:TextureUsages::RENDER_ATTACHMENT|TextureUsages::COPY_SRC,view_formats:&[]});let view=texture.create_view(&TextureViewDescriptor::default());let read=device.create_buffer(&BufferDescriptor {label:None,size:262144,usage:BufferUsages::COPY_DST|BufferUsages::MAP_READ,mapped_at_creation:false});
 let mut encoder=device.create_command_encoder(&CommandEncoderDescriptor::default());{let mut pass=encoder.begin_render_pass(&RenderPassDescriptor {label:None,color_attachments:&[Some(RenderPassColorAttachment {view:&view,depth_slice:None,resolve_target:None,ops:Operations {load:LoadOp::Clear(Color::TRANSPARENT),store:StoreOp::Store}})],..Default::default()});pass.set_pipeline(&pipeline);pass.draw(0..3,0..1);}encoder.copy_texture_to_buffer(TexelCopyTextureInfo {texture:&texture,mip_level:0,origin:Origin3d::ZERO,aspect:TextureAspect::All},TexelCopyBufferInfo {buffer:&read,layout:TexelCopyBufferLayout {offset:0,bytes_per_row:Some(1024),rows_per_image:Some(256)}},size);queue.submit([encoder.finish()]);
 let(tx,rx)=mpsc::channel();read.slice(..).map_async(MapMode::Read,move|result|tx.send(result).unwrap());device.poll(PollType::wait_indefinitely()).unwrap();rx.recv().unwrap().unwrap();let bytes=read.slice(..).get_mapped_range();let mut accepted=0usize;let mut equality_rejected=0usize;
 for reference in 0..256usize {for alpha in 0..256usize {let index=(reference*256+alpha)*4;let expected=if alpha>reference {accepted+=1;[255,0,0,255]} else {if alpha==reference {equality_rejected+=1;}[0,0,0,0]};assert_eq!(&bytes[index..index+4],&expected,"alpha{alpha} reference{reference}");}}
 drop(bytes);read.unmap();let receipt=serde_json::json!({"passed":true,"complete":false,"adapter":info.name,"backend":format!("{:?}",info.backend),"actual_raster_pixels":65536,"accepted_pixels":accepted,"rejected_pixels":65536-accepted,"equality_rejected_cases":equality_rejected,"target_format":"Rgba8Unorm","reference_profile":"normalized native8bit reference /255, strictGREATER","limits":["Actual Vulkan raster/discard readback executes identical production predicate for all256incoming-alpha bytes against all256reference bytes; integer D3D comparison semantics used as independent reference.","Original D3D incoming-alpha precision, filtered/interpolated samples, full draw-state order, blending/depth/shadow passes and native scene framebuffer equivalence remain open."]});std::fs::write("logs/native-alpha-raster-gpu.json",serde_json::to_vec_pretty(&receipt).unwrap()).unwrap();println!("Native alpha GPU raster65536 pixels accepted{accepted} equality rejected{equality_rejected}");
}
